function OfficialBrandLogo({
  id,
  label,
  className = "",
  size = 18,
}: {
  id: string;
  label: string;
  className?: string;
  size?: number;
}) {
  const path = OFFICIAL_BRAND_PATHS[id];
  const color: Record<string, string> = {
    supabase: "#3ECF8E",
    stripe: "#635BFF",
    postgres: "#4169E1",
  };
  if (!path) return null;
  return (
    <svg
      aria-label={label}
      className={className}
      fill={color[id] ?? "currentColor"}
      height={size}
      role="img"
      viewBox="0 0 24 24"
      width={size}
      xmlns="http://www.w3.org/2000/svg"
    >
      <path d={path} />
    </svg>
  );
}

export function getConnectorBrandLogo(id: string, className = "", size = 18): React.ReactNode {
  const aliases: Record<string, string> = {
    gcp: "google-cloud",
    google: "google-drive",
    postgresql: "postgres",
  };
  const canonicalId = aliases[id] ?? id;
  const official = OFFICIAL_BRAND_PATHS[canonicalId];
  if (official) {
    const labels: Record<string, string> = {
      github: "GitHub", figma: "Figma", supabase: "Supabase", stripe: "Stripe",
      vercel: "Vercel", "google-drive": "Google Drive", postgres: "PostgreSQL",
      notion: "Notion", "google-cloud": "Google Cloud",
    };
    return <OfficialBrandLogo id={canonicalId} label={labels[canonicalId] ?? canonicalId} size={size} className={className} />;
  }
  switch (canonicalId) {
    case "canva": return <CanvaLogo size={size} className={className} />;
    case "slack": return <SlackLogo size={size} className={className} />;
    default: return null;
  }
}
